"""Collect existing observations only, without recomputing any field."""
from pathlib import Path
from datetime import datetime,timezone
import json,hashlib
import mpmath as mp
B=Path('research/hydrostatic_state_audit/verification');V=Path('research/hydrostatic_axis_primitive/verification');mp.mp.dps=130
now=datetime.now(timezone.utc).isoformat();sources=[];states=[];regions=['tiny','inner','core','annulus','far','extent10','extent100','extent10000']
for f in sorted(B.glob('hs*.json')):
 d=json.loads(f.read_text())
 if not isinstance(d,dict)or'regions'not in d:continue
 assert d['status']=='DONE';sources.append(f);ex=d['exact']
 states.append(dict(tag=d['tag'],source_sha256=d['source_sha256'],c=d['metadata']['c'],N=d['metadata']['N'],M=d['metadata']['M'],exact={k:ex[k]for k in ['a_float','delta_float','b','E','K','tail_defect']},center_GL=d['center_GL'],regions=d['regions'],axis_derivative_samples=d['axis_derivative_samples'],reconstruction=d['node_reconstruction'],sample_count=len(d['samples']),finished_utc=d['finished_utc']))
assert len(states)==21 and all(d['sample_count']==774 for d in states)
summary=dict(utc=now,status='COMPLETE',states=states,scope='Finite hydrostatic input densities, exact center functionals, finite observations with quadrature comparisons. No global residual enclosures, no steady solutions or original endpoint established.')
(B/'ALL21_SUMMARY.json').write_text(json.dumps(summary,indent=2)+'\n')
text=['# Independent checks of21 hydrostatic trial densities','',f'Completed {now}. Each stored u/tk field has774 independent Cartesian-derivative/full-line-inverse samples. The first12 metadata checks are in METADATA_RECHECK.json; the later9 are in METADATA_EXTENSION.json. All input coefficients and nodes matched bit for bit at the recorded check times. Later export-only metadata edits do not alter these mathematical fields.','', 'The table gives observed abs(R)/Nf peaks. The tiny region is r<0.01, inner is0.01<=r<0.1, core is0.1<=r<1, annulus is1<=r<100, and far is100<=r<=10000 on the prescribed finite grid. These are not uniform suprema or infinite-domain maxima. Samples with Nf=Nv=0 remain undefined, with R recorded, and are never replaced by a denominator floor. The JSON also gives R, Nf, Nv, locations and the separate abs(R)/Nv peaks in every region and at three physical extents.','', '| State | Exact center defect | tiny | inner | core | annulus | far |','|---|---:|---:|---:|---:|---:|---:|']
for d in states:text.append('| '+d['tag']+' | '+format(d['exact']['delta_float'],'.10g')+' | '+' | '.join(format(d['regions'][k]['R_Nf']['R_Nf'],'.8g')for k in regions[:5])+' |')
text+=['','The full-line evaluator has its own manufactured gate and changed quadratures; exact rational center functionals do not use those quadratures. Selected axis peaks have a second multiprecision inverse based on a compact-coordinate polynomial for V2_y and its exact full-tail endpoint (result190). The tables retain the primary rule, so small differences from the second inverse are visible instead of silently overwritten.','', 'The failed hsB_cl3chain_N96 trial has center defect1.39846 and several relative residuals1. It is a failed trial, not a steady state. The free-c trials retain a fixed tail exponent; they cannot establish selection or lack of selection of c. Adding the producer center row does not impose the exact center functional: the D64 and D96 saved fields have exact defects+4.487832440052405e-7 and+2.700193685622116e-8. Compact Gauss rules independently agree with their exact functionals to about1e-12 and3e-13. A finite-difference row evaluated near zero is a distinct functional.','', 'The varying jets, positive and negative center defects, and sampled residuals show no verified convergent hydrostatic sequence. The result does not exclude convergence after changed optimization or discretization, nor existence of any hydrostatic or original profile. Original Setting III remains UNRESOLVED.']
(B/'ALL21_SUMMARY.md').write_text('\n'.join(text)+'\n')
extags=['hsD_c3.0_N64_keep','hsD_c3.0_N96_keep','hsC_c3.0_N96_fine'];axis=[]
for tag in extags:
 f=V/(tag+'.json');d=json.loads(f.read_text());assert d['status']=='DONE';sources.extend([f,V/(tag+'.polynomial.json')]);base=next(x for x in states if x['tag']==tag)
 for pt in d['points']:
  axis.append(dict(tag=tag,region=pt['source_region'],x=0,y=pt['y'],exact_center_defect=base['exact']['delta_float'],values=pt['refinements'][-1]['values'],differences=pt['refinement_differences'],primary_differences=pt['primary_differences'],refinement_settings=[{k:r[k]for k in ['target_digits','working_digits','order','gy_scalar_diff_error']}for r in pt['refinements']]))
assert len(axis)==7
maxdiff={k:{w:str(max(mp.mpf(r['differences'][k][w])for r in axis))for w in ['order24_40','order40_56']}for k in ['V2','R','R_Nf','R_Nv']};maxprimary={k:str(max(mp.mpf(r['primary_differences'][k])for r in axis))for k in ['g','gy','V2','R','R_Nf','R_Nv']}
(V/'EXTENSION_SUMMARY.json').write_text(json.dumps(dict(utc=now,status='COMPLETE',rows=axis,max_refinement_differences=maxdiff,max_primary_differences=maxprimary,scope='Seven finite axis witnesses, not uniform maxima or interval error bounds.'),indent=2)+'\n')
t=['# Seven additional independent axis witnesses','',f'Completed {now}. The primary inverse was independently checked at these selected axis samples by a second full-tail construction. The exact polynomial for V2_y includes the entire exterior integral through its endpoint; only a finite physical integral0..y remains.','', '| State | Region | y | R | Nf | Nv | abs(R)/Nf | abs(R)/Nv |','|---|---|---:|---:|---:|---:|---:|---:|']
for r in axis:t.append('| '+r['tag']+' | '+r['region']+' | '+format(r['y'],'.12g')+' | '+' | '.join(mp.nstr(mp.mpf(r['values'][k]),12)for k in ['R','Nf','Nv','R_Nf','R_Nv'])+' |')
t+=['',f'Maximum40/56-point observed difference in abs(R)/Nf: {mp.nstr(mp.mpf(maxdiff["R_Nf"]["order40_56"]),8)}. Maximum difference from the primary20/112-point full-line rule in that ratio: {mp.nstr(mp.mpf(maxprimary["R_Nf"]),8)}. The latter occurs in the D64 core, where the primitive gives0.00061908603359812 compared with0.00061896454885758 from the primary rule. This correction is small relative to that residual but is retained. Annulus and far witnesses agree much more closely. These are measured differences, not validated enclosures.','', 'Together with the original11 witnesses this supplies18 axis checks at independently changed precision and quadrature. The actual Opus5.5 lead reviewed the primitive proof at09:13 and independently tested a rational three-mode manufactured input at three positive radii; its warning about differentiating through fixed-precision inversions was checked against this implementation. AxisPrimitive.coordinate uses Newton iteration with the current mp.eps and raises on nonconvergence; its stopping threshold adapts when mp.diff increases precision. The scalar derivative comparisons and70/100-digit outputs remain in the per-state files. No profile existence assertion is made.']
(V/'EXTENSION_SUMMARY.md').write_text('\n'.join(t)+'\n')
for folder,names in [(B,['ALL21_SUMMARY.json','ALL21_SUMMARY.md']),(V,['EXTENSION_SUMMARY.json','EXTENSION_SUMMARY.md'])]:
 manifest={str(p):hashlib.sha256(p.read_bytes()).hexdigest()for p in [Path(__file__),*[folder/n for n in names],*sources]};(folder/(names[0].replace('.json','_MANIFEST.json'))).write_text(json.dumps(manifest,indent=2)+'\n')
print('COMPLETE',len(states),'states',len(axis),'axis witnesses',now)
print('axis max refinement',mp.nstr(mp.mpf(maxdiff['R_Nf']['order40_56']),8),'primary',mp.nstr(mp.mpf(maxprimary['R_Nf']),8))
